package replacements

import (
	"path/filepath"
	"strings"
	"testing"
)

const generatedContainer = `//go:build !diogen

// Code generated by diogen. DO NOT EDIT.

package diogen

import (
	sql "gitlab.com/gorib/sql"
	paymentProto "gitlab.com/sherpa-erp/sherpa/api/payment"
	invoiceGrpc "gitlab.com/sherpa-erp/sherpa/dungeon/domain/invoice/cmd/grpc"
	rentAdapter "gitlab.com/sherpa-erp/sherpa/dungeon/domain/rent/adapter"
	pubsub "gitlab.com/sherpa-erp/sherpa/dungeon/pkg/pubsub"
	pubsubModel "gitlab.com/sherpa-erp/sherpa/dungeon/pkg/pubsub/model"
)

type Local interface{ Ping() }

type Replacements struct {
	SqlDb                            sql.Db
	PaymentProtoPaymentServiceClient paymentProto.PaymentServiceClient
	PubsubCommand                    pubsub.Command[pubsubModel.Quantity, pubsubModel.GwsResult]
	LocalThing                       Local
	InvoiceGrpcInvoiceManagement     interface {
		invoiceGrpc.InvoiceManagement
		rentAdapter.InvoiceManagement
	}
}
`

func writeContainer(t *testing.T, body string) Container {
	t.Helper()
	inTempDir(t)
	writeGo(t, filepath.Join("config", "diogen", "di_gen.go"), body)
	return Container{
		File:    filepath.Join("config", "diogen", "di_gen.go"),
		Dir:     filepath.Join("config", "diogen"),
		Package: "diogen",
	}
}

func TestReadSeams(t *testing.T) {
	c := writeContainer(t, generatedContainer)

	seams, err := ReadSeams(c, "gitlab.com/sherpa-erp/sherpa/dungeon/config/diogen")
	if err != nil {
		t.Fatal(err)
	}

	want := []Seam{
		{Field: "SqlDb", Types: []TypeRef{{"gitlab.com/gorib/sql", "Db"}}},
		{Field: "PaymentProtoPaymentServiceClient", Types: []TypeRef{
			{"gitlab.com/sherpa-erp/sherpa/api/payment", "PaymentServiceClient"},
		}},
		// The instantiation is dropped: mockgen mocks the generic interface.
		{Field: "PubsubCommand", Types: []TypeRef{
			{"gitlab.com/sherpa-erp/sherpa/dungeon/pkg/pubsub", "Command"},
		}},
		{Field: "LocalThing", Types: []TypeRef{
			{"gitlab.com/sherpa-erp/sherpa/dungeon/config/diogen", "Local"},
		}},
		{Field: "InvoiceGrpcInvoiceManagement", Types: []TypeRef{
			{"gitlab.com/sherpa-erp/sherpa/dungeon/domain/invoice/cmd/grpc", "InvoiceManagement"},
			{"gitlab.com/sherpa-erp/sherpa/dungeon/domain/rent/adapter", "InvoiceManagement"},
		}},
	}

	if len(seams) != len(want) {
		t.Fatalf("read %d seams, want %d: %+v", len(seams), len(want), seams)
	}
	for i, w := range want {
		got := seams[i]
		if got.Field != w.Field || len(got.Types) != len(w.Types) {
			t.Errorf("[%d] = %+v, want %+v", i, got, w)
			continue
		}
		for j := range w.Types {
			if got.Types[j] != w.Types[j] {
				t.Errorf("[%d].Types[%d] = %v, want %v", i, j, got.Types[j], w.Types[j])
			}
		}
	}

	if seams[0].Composite() {
		t.Error("a one-type seam reports itself as composite")
	}
	if !seams[4].Composite() {
		t.Error("a seam over two interfaces does not report itself as composite")
	}
}

// A di.Tags(tag) collection: []T, not an interface
func TestReadSeamsForTagCollection(t *testing.T) {
	c := writeContainer(t, `package diogen

import fw "gitlab.com/gorib/di/testdata/cases/include_tags/framework"

type Replacements struct {
	FwHandlerAsHandlerTag []fw.Handler
}
`)

	seams, err := ReadSeams(c, "example.com/svc/config/diogen")
	if err != nil {
		t.Fatal(err)
	}
	if len(seams) != 1 {
		t.Fatalf("read %d seams, want 1: %+v", len(seams), seams)
	}
	got := seams[0]
	wantType := TypeRef{"gitlab.com/gorib/di/testdata/cases/include_tags/framework", "Handler"}
	if got.Field != "FwHandlerAsHandlerTag" || len(got.Types) != 1 || got.Types[0] != wantType {
		t.Errorf("= %+v, want Field=FwHandlerAsHandlerTag Types=[%v]", got, wantType)
	}
	if got.Composite() {
		t.Error("a single-element []T collection reports itself as composite")
	}
}

func TestReadSeamsEmptyStruct(t *testing.T) {
	c := writeContainer(t, "package diogen\n\ntype Replacements struct{}\n")

	seams, err := ReadSeams(c, "example.com/svc/config/diogen")
	if err != nil {
		t.Fatal(err)
	}
	if len(seams) != 0 {
		t.Errorf("a container with no seam produced %+v", seams)
	}
}

func TestReadSeamsWithoutReplacements(t *testing.T) {
	c := writeContainer(t, "package diogen\n\ntype Application struct{}\n")

	_, err := ReadSeams(c, "example.com/svc/config/diogen")
	if err == nil {
		t.Fatal("a container without Replacements read cleanly")
	}
	if !strings.Contains(err.Error(), "Replacements") {
		t.Errorf("the error does not say what is missing: %v", err)
	}
}

const leafContainer = `package diogen

import (
	env "gitlab.com/gorib/env"
	sql "gitlab.com/gorib/sql"
	pry "gitlab.com/gorib/pry"
	repo "example.com/svc/domain/x/adapter/postgres"
	service "example.com/svc/domain/x/service"
	adapter "example.com/svc/domain/x/adapter/security"
)

type Replacements struct {
	SqlDb           sql.Db
	PryLogger       pry.Logger
	ServiceRepo     service.Repo
	ServiceSecurity service.Security
	Branched        service.Branched
}

func InitAppWith(replacements Replacements) (_ *Application, err error) {
	container.sqlDb = replacements.SqlDb

	if container.sqlDb == nil {
		s, err := sql.NewDb(env.NeedValue[string]("DB_DRIVER"), env.NeedValue[string]("DB_DSN"))
		if err != nil {
			return nil, err
		}
		container.sqlDb = s
	}

	if v, ok := container.sqlDb.(io.Closer); ok {
		container.closers = append(container.closers, v)
	}

	container.pryLogger = replacements.PryLogger

	if container.pryLogger == nil {
		container.pryLogger = pry.New(env.Value("LOGLEVEL", "info"))
	}

	container.serviceRepo = replacements.ServiceRepo

	if container.serviceRepo == nil {
		container.serviceRepo = repo.NewRepo(container.sqlDb, container.pryLogger)
	}

	container.serviceSecurity = replacements.ServiceSecurity

	if container.serviceSecurity == nil {
		container.serviceSecurity = adapter.NewFactory()
	}

	container.branched = replacements.Branched

	if container.branched == nil ` + "&&" + ` mode == "fast" {
		container.branched = service.NewFast()
	}

	return container, nil
}
`

func TestReadSeamsMarksLeaves(t *testing.T) {
	c := writeContainer(t, leafContainer)

	seams, err := ReadSeams(c, "example.com/svc/config/diogen")
	if err != nil {
		t.Fatal(err)
	}

	want := map[string]bool{
		"SqlDb":     true,
		"PryLogger": true,
		// Built from the db and the logger, so it is a node, not a boundary.
		"ServiceRepo":     false,
		"ServiceSecurity": true,
		// A branch condition beside the nil guard does not hide the leaf.
		"Branched": true,
	}
	if len(seams) != len(want) {
		t.Fatalf("read %d seams, want %d", len(seams), len(want))
	}
	for _, seam := range seams {
		if seam.Leaf != want[seam.Field] {
			t.Errorf("%s: Leaf = %v, want %v", seam.Field, seam.Leaf, want[seam.Field])
		}
	}
}

const closureContainer = `package diogen

import (
	env "gitlab.com/gorib/env"
	sql "gitlab.com/gorib/sql"
	pry "gitlab.com/gorib/pry"
	repo "example.com/svc/domain/x/adapter/postgres"
	service "example.com/svc/domain/x/service"
)

type Replacements struct {
	SqlDb        sql.Db
	PryLogger    pry.Logger
	ServiceRepo  service.Repo
	ServiceCache service.Cache
	HandlerAsH   []service.Handler
}

func InitAppWith(replacements Replacements) (_ *Application, err error) {
	container.sqlDb = replacements.SqlDb
	container.pryLogger = replacements.PryLogger
	container.serviceRepo = replacements.ServiceRepo
	container.serviceCache = replacements.ServiceCache
	container.handlerAsH = replacements.HandlerAsH

	buildSqlDb := diogenBuild("gitlab.com/gorib/sql.NewDb", func(name string) error {
		if container.sqlDb == nil {
			s, err := sql.NewDb(env.NeedValue[string]("DB_DRIVER"), env.NeedValue[string]("DB_DSN"))
			if err != nil {
				return err
			}
			container.closers.add(0, name, s.Close)
			container.sqlDb = s
		}
		return nil
	})

	buildPryLogger := diogenBuild("gitlab.com/gorib/pry.New", func(name string) error {
		if container.pryLogger == nil {
			s := pry.New(env.Value("LOGLEVEL", "info"))
			container.pryLogger = s
		}
		return nil
	})

	buildServiceRepo := diogenBuild("example.com/svc/domain/x/adapter/postgres.NewRepo", func(name string) error {
		if container.serviceRepo == nil {
			if err := diogenNeed(buildSqlDb, buildPryLogger); err != nil {
				return err
			}
			s := repo.NewRepo(container.sqlDb, container.pryLogger)
			container.serviceRepo = s
		}
		return nil
	})

	buildServiceCache := diogenBuild("", func(name string) error {
		if container.serviceCache == nil ` + "&&" + ` mode() {
			if err := diogenBuild("example.com/svc/domain/x/service.NewMemory", func(name string) error {
				s := service.NewMemory()
				container.serviceCache = s
				return nil
			})(); err != nil {
				return err
			}
		}
		if container.serviceCache == nil ` + "&&" + ` !mode() {
			if err := diogenBuild("example.com/svc/domain/x/service.NewPersistent", func(name string) error {
				if err := buildSqlDb(); err != nil {
					return err
				}
				s := service.NewPersistent(container.sqlDb)
				container.serviceCache = s
				return nil
			})(); err != nil {
				return err
			}
		}
		return nil
	})

	buildHandlerAsH := diogenBuild("di.Tags(\"h\")", func(name string) error {
		if container.handlerAsH == nil {
			if err := buildServiceHandler(); err != nil {
				return err
			}
			container.handlerAsH = []service.Handler{container.serviceHandler}
		}
		return nil
	})

	if err := buildServiceRepo(); err != nil {
		return nil, err
	}

	return container, nil
}
`

// A value of a type the container cannot name lives in a local, not in a field.
const localContainer = `package diogen

import (
	env "gitlab.com/gorib/env"
	lib "example.com/svc/lib"
	service "example.com/svc/domain/x/service"
)

type Replacements struct {
	ServiceRepo  service.Repo
	ServiceClock service.Clock
}

func InitAppWith(replacements Replacements) (_ *Application, err error) {
	container.serviceRepo = replacements.ServiceRepo
	container.serviceClock = replacements.ServiceClock

	libConn := diogenZero1(lib.NewConn)

	buildLibConn := diogenBuild("example.com/svc/lib.NewConn", func(name string) error {
		s := lib.NewConn(env.NeedValue[string]("DB_DSN"))
		libConn = s
		return nil
	})

	buildServiceRepo := diogenBuild("example.com/svc/domain/x/service.NewRepo", func(name string) error {
		if container.serviceRepo == nil {
			if err := buildLibConn(); err != nil {
				return err
			}
			s := service.NewRepo(libConn)
			container.serviceRepo = s
		}
		return nil
	})

	buildServiceClock := diogenBuild("example.com/svc/domain/x/service.NewClock", func(name string) error {
		if container.serviceClock == nil {
			s := service.NewClock()
			container.serviceClock = s
		}
		return nil
	})

	if err := diogenNeed(buildServiceRepo, buildServiceClock); err != nil {
		return nil, err
	}

	return container, nil
}
`

func TestReadSeamsCountsAReadOfALocal(t *testing.T) {
	c := writeContainer(t, localContainer)

	seams, err := ReadSeams(c, "example.com/svc/config/diogen")
	if err != nil {
		t.Fatal(err)
	}

	want := map[string]bool{"ServiceRepo": false, "ServiceClock": true}
	if len(seams) != len(want) {
		t.Fatalf("read %d seams, want %d", len(seams), len(want))
	}
	for _, seam := range seams {
		if seam.Leaf != want[seam.Field] {
			t.Errorf("%s: Leaf = %v, want %v", seam.Field, seam.Leaf, want[seam.Field])
		}
	}
}

func TestReadSeamsMarksLeavesInsideBuildClosures(t *testing.T) {
	c := writeContainer(t, closureContainer)

	seams, err := ReadSeams(c, "example.com/svc/config/diogen")
	if err != nil {
		t.Fatal(err)
	}

	want := map[string]bool{
		"SqlDb":       true,
		"PryLogger":   true,
		"ServiceRepo": false,
		// One branch builds from the db, so replacing it cuts that branch out.
		"ServiceCache": false,
		"HandlerAsH":   false,
	}
	if len(seams) != len(want) {
		t.Fatalf("read %d seams, want %d", len(seams), len(want))
	}
	for _, seam := range seams {
		if seam.Leaf != want[seam.Field] {
			t.Errorf("%s: Leaf = %v, want %v", seam.Field, seam.Leaf, want[seam.Field])
		}
	}
}

const closeWithContainer = `package diogen

import (
	"time"

	env "gitlab.com/gorib/env"
	sql "gitlab.com/gorib/sql"
	service "example.com/svc/domain/x/service"
)

type Replacements struct {
	SqlDb       sql.Db
	ServiceRepo service.Repo
}

func InitAppWith(replacements Replacements) (_ *Application, err error) {
	container.sqlDb = replacements.SqlDb
	container.serviceRepo = replacements.ServiceRepo

	buildSqlDb := diogenBuild("gitlab.com/gorib/sql.Open", func(name string) error {
		if container.sqlDb == nil {
			closeWith := sql.CloseWithin(env.Value("DB_CLOSE_TIMEOUT", time.Second))
			s := sql.Open()
			container.closers.add(0, name, func() error {
				return closeWith(s)
			})
			container.sqlDb = s
		}
		return nil
	})

	buildServiceRepo := diogenBuild("example.com/svc/domain/x/service.NewRepo", func(name string) error {
		if container.serviceRepo == nil {
			if err := buildSqlDb(); err != nil {
				return err
			}
			s := service.NewRepo(container.sqlDb)
			container.serviceRepo = s
		}
		return nil
	})

	if err := buildServiceRepo(); err != nil {
		return nil, err
	}
	return container, nil
}
`

// di.CloseWith adds a local and a closer to the block; neither is a read of the graph.
func TestReadSeamsCloseWithLeavesALeafALeaf(t *testing.T) {
	c := writeContainer(t, closeWithContainer)

	seams, err := ReadSeams(c, "example.com/svc/config/diogen")
	if err != nil {
		t.Fatal(err)
	}

	want := map[string]bool{"SqlDb": true, "ServiceRepo": false}
	if len(seams) != len(want) {
		t.Fatalf("read %d seams, want %d", len(seams), len(want))
	}
	for _, seam := range seams {
		if seam.Leaf != want[seam.Field] {
			t.Errorf("%s: Leaf = %v, want %v", seam.Field, seam.Leaf, want[seam.Field])
		}
	}
}

const paramsContainer = `package diogen

import (
	"context"

	sql "gitlab.com/gorib/sql"
	di "example.com/svc/config/di"
	service "example.com/svc/domain/x/service"
)

type Replacements struct {
	SqlDb       sql.Db
	ServiceRepo service.Repo
}

func InitAppWith(ctx context.Context, cfg *di.Config, replacements Replacements) (_ *Application, err error) {
	container.sqlDb = replacements.SqlDb

	if container.sqlDb == nil ` + "&&" + ` cfg.Db != "" {
		container.sqlDb = sql.Open(ctx, cfg.Db)
	}

	container.serviceRepo = replacements.ServiceRepo

	if container.serviceRepo == nil {
		container.serviceRepo = service.NewRepo(ctx, container.sqlDb)
	}

	return container, nil
}
`

// A parameter is what the caller hands in, not a node of the graph: reading one
// leaves a leaf a leaf.
func TestReadSeamsParametersAreNotContainerReads(t *testing.T) {
	c := writeContainer(t, paramsContainer)

	seams, err := ReadSeams(c, "example.com/svc/config/diogen")
	if err != nil {
		t.Fatal(err)
	}

	want := map[string]bool{"SqlDb": true, "ServiceRepo": false}
	if len(seams) != len(want) {
		t.Fatalf("read %d seams, want %d", len(seams), len(want))
	}
	for _, seam := range seams {
		if seam.Leaf != want[seam.Field] {
			t.Errorf("%s: Leaf = %v, want %v", seam.Field, seam.Leaf, want[seam.Field])
		}
	}
}

// A container generated before diogenBuild, still in services until they regenerate.
const tagCollectionContainer = `package diogen

type Handler interface{ Path() string }
type Named interface{ Name() string }

type Replacements struct {
	Multi_tagHandlerAsH []Handler
	Multi_tagNamedAsN   []Named
}

func InitAppWith(replacements Replacements) (_ *Application, err error) {
	s := NewBoth()
	container.multi_tagBothAsMulti_tagHandler = s
	container.multi_tagBothAsMulti_tagNamed = s

	if replacements.Multi_tagHandlerAsH != nil {
		container.multi_tagHandlerAsH = replacements.Multi_tagHandlerAsH
	} else {
		container.multi_tagHandlerAsH = []Handler{container.multi_tagBothAsMulti_tagHandler}
	}

	if replacements.Multi_tagNamedAsN != nil {
		container.multi_tagNamedAsN = replacements.Multi_tagNamedAsN
	} else {
		container.multi_tagNamedAsN = []Named{container.multi_tagBothAsMulti_tagNamed}
	}

	return container, nil
}
`

func TestReadSeamsTagCollectionsAreNotLeaves(t *testing.T) {
	c := writeContainer(t, tagCollectionContainer)

	seams, err := ReadSeams(c, "example.com/svc/config/diogen")
	if err != nil {
		t.Fatal(err)
	}
	if len(seams) != 2 {
		t.Fatalf("read %d seams, want 2: %+v", len(seams), seams)
	}
	for _, seam := range seams {
		if seam.Leaf {
			t.Errorf("%s: Leaf = true, want false", seam.Field)
		}
	}
}

// A container generated before diogenBuild, still in services until they regenerate.
const skippableTagCollectionContainer = `package diogen

type Handler interface{ Path() string }

type Replacements struct {
	TagsHandlerAsHandlerTag []Handler
}

func InitAppWith(replacements Replacements) (_ *Application, err error) {
	container.tagsHandlerAsHandlerTag = replacements.TagsHandlerAsHandlerTag

	if container.tagsHandlerAsHandlerTag == nil {
		s := NewA()
		container.tagsHandlerFromNewA = s
	}

	if container.tagsHandlerAsHandlerTag == nil {
		s := NewB()
		container.tagsHandlerFromNewB = s
	}

	if container.tagsHandlerAsHandlerTag == nil {
		container.tagsHandlerAsHandlerTag = []Handler{container.tagsHandlerFromNewA, container.tagsHandlerFromNewB}
	}

	return container, nil
}
`

func TestReadSeamsSkippableTagCollectionIsNotALeaf(t *testing.T) {
	c := writeContainer(t, skippableTagCollectionContainer)

	seams, err := ReadSeams(c, "example.com/svc/config/diogen")
	if err != nil {
		t.Fatal(err)
	}
	if len(seams) != 1 {
		t.Fatalf("read %d seams, want 1: %+v", len(seams), seams)
	}
	if seams[0].Leaf {
		t.Errorf("%s: Leaf = true, want false", seams[0].Field)
	}
}

func TestReadSeamsWithoutInitAppWith(t *testing.T) {
	c := writeContainer(t, "package diogen\n\nimport sql \"gitlab.com/gorib/sql\"\n\ntype Replacements struct{ SqlDb sql.Db }\n")

	seams, err := ReadSeams(c, "example.com/svc/config/diogen")
	if err != nil {
		t.Fatal(err)
	}
	if len(seams) != 1 || seams[0].Leaf {
		t.Errorf("with no InitAppWith to read, nothing can be called a leaf: %+v", seams)
	}
}
